{
  "name": "get_invoice",
  "description": "Fetch one invoice by id. Use when the user asks about a specific invoice amount, status or due date. Do not use for listing invoices.",
  "input_schema": {
    "type": "object",
    "properties": {
      "invoice_id": {
        "type": "string",
        "description": "Invoice id, for example INV-20417"
      },
      "include_line_items": {
        "type": "boolean",
        "description": "Return line items as well as totals"
      }
    },
    "required": ["invoice_id", "include_line_items"],
    "additionalProperties": false
  }
}
